examples.source:
graph transformExample {
  transform result {
    value = ctx.value
  }
}

graph resourceExample {
  node lookup : httpResource {
    input {
      resourceId = ctx.resourceId
      params = {}
    }
  }
  transform result {
    payload = lookup.output.payload
  }
}

graph namedPortsExample {
  node lookup : httpResource {
    input {
      resourceId = ctx.resourceId
      params = {}
    }
  }
  transform result {
    payload = lookup.output.payload
  }
}

graph typedShapeExample {
  schema Profile {
    name: String
    note: String?
  }
  transform result {
    profile: Profile = { name: ctx.name, note: ctx.note }
    labels = [coalesce(ctx.label, "standard")]
  }
}

graph decisionExample {
  decision_table policy(score = ctx.score) hit=unique -> { decision: String } {
    rule (score: score >= 120) -> { decision: "accept" }
    otherwise -> { decision: "review" }
  }
}

graph boundaryExample {
  decision_table policy(score = ctx.score) hit=unique -> { decision: String } {
    rule (score: score < 120) -> { decision: "below" }
    rule (score: score == 120) -> { decision: "at" }
    rule (score: score > 120) -> { decision: "above" }
    otherwise -> { decision: "review" }
  }
}

graph cancelPolicyExample {
  node order : httpResource {
    input {
      resourceId = ctx.orderResourceId
      params = {}
    }
  }
  node liability : httpResource {
    input {
      resourceId = ctx.liabilityResourceId
      params = {}
    }
  }
  node cityPolicy : httpResource {
    input {
      resourceId = ctx.cityPolicyResourceId
      params = {}
    }
  }
  node history : httpResource {
    input {
      resourceId = ctx.historyResourceId
      params = {}
    }
  }
  decision_table policy(malicious = ctx.malicious, responsibility = ctx.responsibility) hit=unique -> { decision: String } {
    rule (malicious: malicious == true) -> { decision: "MANUAL_REVIEW" }
    rule (malicious: malicious == false, responsibility: responsibility == "DRIVER") -> { decision: "WAIVE_FULL" }
    otherwise -> { decision: "RETAIN" }
  }
  transform facts {
    orderPayload = order.output.payload
    liabilityPayload = liability.output.payload
    cityPolicyPayload = cityPolicy.output.payload
    historyPayload = history.output.payload
  }
}

graph designOnlyExample {
  node assess : "risk:eligibility" {
    input {
      score = ctx.score
      amount = ctx.amount
    }
  }
  transform result {
    eligible = assess.output.eligible
  }
}
